# Global help/version handling - replicates observed behavior with priority version > help
def handle_global_help_version():
    argv = sys.argv[1:]
    # version has highest priority anywhere
    if "--version" in argv:
        sys.stdout.write(VERSION)
        sys.exit(0)
    # detect help flags
    has_help = any(tok in ("--help","-h") for tok in argv)
    if not has_help:
        return
    # help handling: we need to decide which help to show based on argv
    # Use rules derived from observations
    help_indices = [i for i, tok in enumerate(argv) if tok in ("--help","-h")]
    first_help = help_indices[0]
    has_all = any(tok in ("--all","-a") for tok in argv)
    # Look for target subcommand after first help (skip options that start with -)
    target_after = None
    for tok in argv[first_help+1:]:
        if tok.startswith("-"):
            continue
        if tok in KNOWN:
            target_after = tok
            break
        # if token is not known but not starting with -, it's an unknown argument; treat as no target
        if not tok.startswith("-"):
            break
    if target_after is not None:
        # found subcommand after help flag
        mapping = {"ls":HELP_LS,"index":HELP_INDEX,"info":HELP_INFO,"histogram":HELP_HISTOGRAM,"topn":HELP_TOPN,"xml":HELP_XML,"json":HELP_JSON,"graph":HELP_GRAPH,"cgi":HELP_CGI,"gui":HELP_GUI,"ui":HELP_UI,"help":HELP_HELP}
        if target_after in mapping:
            sys.stdout.write(mapping[target_after])
            sys.exit(0)
    # look before help for a subcommand that appears immediately before help (like "ls --help")
    target_before = None
    for tok in reversed(argv[:first_help]):
        if tok.startswith("-"):
            continue
        if tok in KNOWN:
            target_before = tok
            break
        if not tok.startswith("-"):
            break
    if target_before is not None:
        mapping = {"ls":HELP_LS,"index":HELP_INDEX,"info":HELP_INFO,"histogram":HELP_HISTOGRAM,"topn":HELP_TOPN,"xml":HELP_XML,"json":HELP_JSON,"graph":HELP_GRAPH,"cgi":HELP_CGI,"gui":HELP_GUI,"ui":HELP_UI,"help":HELP_HELP}
        if target_before in mapping:
            sys.stdout.write(mapping[target_before])
            sys.exit(0)
    # handle --all case when no specific target
    if has_all:
        sys.stdout.write(HELP_ALL)
        sys.exit(0)
    # duplicate help flags => HELP_HELP
    if len(help_indices) >= 2:
        sys.stdout.write(HELP_HELP)
        sys.exit(0)
    # fallback based on presence of global flags before help
    has_global_before = any(tok in ("--debug","--verbose","-v","--quiet","-q") for tok in argv[:first_help])
    if has_global_before:
        sys.stdout.write(HELP_HELP)
        sys.exit(0)
    else:
        sys.stdout.write(MAIN_HELP)
        sys.exit(0)

