            eprint("Requested path not found")
        sys.exit(1)
    # Build JSON with bug replication for -s and -x
    # Original has bug where filtered entries result in "," placeholders.
    # We need to replicate that bug: when -x or -s filters out an entry, it leaves a blank entry that results in ",\\n,\\n" in output.
    # Specifically, for json -x, it filtered files and left commas but no objects, resulting in "[\\n,\\n,\\n,\\n\\n]"
    # For json -s, similarly.
    # We need to replicate: when we have children list, we filter each entry, but if filtered, we still output a placeholder that is just empty, leading to extra commas.
    # The original code likely does: for each child, if should_include, output json, else output "" and still add comma, leading to ",\\n,\\n"
    # We'll replicate by: building list of strings for children, where filtered entries become "" (empty string), and then joining with ",\\n"
    def should_include(entry):
        sz=entry["size_apparent"] if apparent else entry["size_actual"]
        if min_size is not None and sz < min_size:
            return False
        if exclude_files and not (entry.get("is_dir") or "count" in entry):
            return False
        return True
    def build_json(node, indent=0):
        # Build JSON string for node
        # We will manually construct to replicate bug
        lines=[]
        ind="  "*indent
        lines.append(f'{ind}{{')
        lines.append(f'{ind}  "name": "{node["name"]}",')
        # For root, include count
        if "count" in node:
            lines.append(f'{ind}  "count": {node["count"]},')
        lines.append(f'{ind}  "size_apparent": {node["size_apparent"]},')
        lines.append(f'{ind}  "size_actual": {node["size_actual"]}')
        children=node.get("children",[])
        if children:
            # Need to handle filtered children with bug
            child_strs=[]
            for child in children:
                if should_include(child):
                    # Recursively build child JSON
                    if child.get("is_dir") or "count" in child:
                        # dir
                        child_json=build_json(child, indent+1)
                        child_strs.append(child_json)
                    else:
                        # file
                        cind="  "*(indent+1)
                        child_strs.append(f'{cind}{{\\n{cind}  "name": "{child["name"]}",\\n{cind}  "size_apparent": {child["size_apparent"]},\\n{cind}  "size_actual": {child["size_actual"]}\\n{cind}}}')
                else:
                    # Filtered: produce empty placeholder that will cause extra comma when joined
                    # For dirs that are filtered, the original still produced "," but not sure
                    # For json -x with only dirs (no files), it produced "[\\n,\\n,\\n,\\n\\n]" which is 4 commas for 3 files+ maybe?
                    # Actually for topn -x with 3 files, it had "[\\n,\\n,\\n,\\n\\n]" -> 4 entries of empty? Wait topn -x had 3 files, but output showed 4 commas? Let's see: "children": [\\n,\\n,\\n,\\n\\n] -> that's 4 empty entries for 5 files? Actually topn had 5 files, with -x it showed 4 commas? Hmm.
                    # We'll replicate by adding an empty string for each filtered entry, which when joined with ",\\n" will produce ",\\n,\\n"
                    child_strs.append("")
            # Now join child_strs with ",\\n"
            # The original bug produces a leading comma before first filtered entry? For json -x with all files filtered, it had "[\\n,\\n,\\n,\\n\\n]" -> leading ",\\n" before first empty?
            # Let's examine: json -x for /tmp/topn_test with 5 files all filtered: output was "  \"children\": [\\n,\\n,\\n,\\n,\\n\\n  ]\\n" -> that's 5 commas? Actually count the commas: between [ and ] there were ",\\n,\\n,\\n,\\n\\n" -> that's 4 commas plus maybe? Let's count: string ",\\n,\\n,\\n,\\n" has 4 commas. For 5 files, that would be 5 entries, but 4 commas between? Hmm.
            # The output for -x with 5 files: "  \"children\": [\\n,\\n,\\n,\\n,\\n\\n  ]" -> inside brackets, there are 4 lines each with "," then newline, plus final newline. That's 4 commas for 5 filtered entries? Not matching.
            # Let's just implement simple: if any filtered, we output them as empty strings, and join with ",\\n" will produce correct number of commas.
            # For 5 filtered entries, joining 5 empty strings with ",\\n" gives ",\\n,\\n,\\n,\\n" (4 separators). But original showed 4 commas for 5 entries? Let's check again: for -x with 5 files, output was "[\\n,\\n,\\n,\\n,\\n\\n]" -> that's 4 commas? Actually between 5 items, there are 4 separators, so joining 5 empties gives 4 separators, which matches 4 commas. But original showed 4 commas? The string ",\\n,\\n,\\n,\\n" has 4 commas, correct for 5 items.
            # So our method of joining empty strings will produce 4 commas, which matches.

            # For mixed case where some filtered and some not, the original showed for -s with min_size 5000 and 5 files where only file5 kept: output was "[\\n    { file5 },\\n,\\n,\\n,\\n\\n]" -> that is file5 plus 4 empties, with commas between.
            # Joining list where first is file json, rest 4 empties, with ",\\n" gives "file5,\\n,\\n,\\n,\\n" -> that's file5, then , then empty, etc. That matches: "file5 ,\\n ,\\n ,\\n ,\\n".

            # So we will join child_strs with ",\\n"
            joined = ",\\n".join(child_strs)
            # Now wrap
            lines.append(f'{ind}  "children": [')
            # Split joined into lines and add
            if joined:
                # Need to ensure we add the joined content as is
                # The child_strs already contain their own internal newlines and indentation, so we just add joined
                lines.append(joined)
            lines.append(f'{ind}  ]')
        lines.append(f'{ind}}}')
        return "\\n".join(lines)
    # For root, name should be path, not basename, but our node name is basename? For root, we stored name as basename of path, but for json root, original shows "name": "/tmp/... (full path)". So we need to handle root name specially.
    # Our nodes dict stores root with key being full path, but node's name is basename, not full path. For json, we should output full path for root.
    # So we will override root name to norm_path
    node["name"]=norm_path
    output=build_json(node, 0)
    sys.stdout.write(output+"\\n")

